using System;using System.Collections.Generic;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public sealed class TransferDrawer:Border {
 readonly StackPanel tasks=new StackPanel();readonly TextBlock empty;readonly Dictionary<FileTransfer,Grid> rows=new Dictionary<FileTransfer,Grid>();public Action CloseRequested;
 public TransferDrawer(){Width=PaneLayouts.Get("transfers.width",390);MaxWidth=640;HorizontalAlignment=HorizontalAlignment.Right;VerticalAlignment=VerticalAlignment.Stretch;Margin=new Thickness(0,0,0,0);Background=Theme.Surface;BorderBrush=Theme.Line;BorderThickness=new Thickness(1,0,0,0);Padding=new Thickness(0);var dock=new DockPanel{Margin=new Thickness(22)};var header=new Grid{Height=38,Margin=new Thickness(0,0,0,18)};header.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});header.Children.Add(Theme.Text("传输任务",20,Theme.Ink,false,true));var close=Theme.IconAction("X","",()=>{if(CloseRequested!=null)CloseRequested();});close.Width=32;Grid.SetColumn(close,1);header.Children.Add(close);DockPanel.SetDock(header,Dock.Top);dock.Children.Add(header);empty=Theme.Text("暂无传输任务",14,Theme.Muted);tasks.Children.Add(empty);dock.Children.Add(new ScrollViewer{Content=tasks,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});var layout=new Grid();layout.Children.Add(dock);var edge=new PaneEdgeHandle("transfers.width",390,300,640,()=>Width,value=>Width=value,()=>{var owner=Parent as Grid;return owner==null?640:owner.ColumnDefinitions[1].ActualWidth-12;},-1){HorizontalAlignment=HorizontalAlignment.Left};Panel.SetZIndex(edge,1);layout.Children.Add(edge);Child=layout;Loaded+=(s,e)=>ClampWidth();SizeChanged+=(s,e)=>ClampWidth();}
 void ClampWidth(){var owner=Parent as Grid;if(owner==null||owner.ColumnDefinitions.Count<2)return;double available=owner.ColumnDefinitions[1].ActualWidth;if(available>0)MaxWidth=Math.Max(300,Math.Min(640,available-12));}
 public void Update(IEnumerable<Tuple<FileTransferQueue,FileTransfer>> jobs){var all=jobs.ToArray();empty.Visibility=all.Length==0?Visibility.Visible:Visibility.Collapsed;foreach(var removed in rows.Keys.Where(x=>!all.Any(j=>object.ReferenceEquals(j.Item2,x))).ToArray()){tasks.Children.Remove(rows[removed]);rows.Remove(removed);}foreach(var entry in all){var job=entry.Item2;Grid card;if(!rows.TryGetValue(job,out card)){card=new Grid{Margin=new Thickness(0,0,0,18)};card.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});card.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});card.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});card.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});card.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});card.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var name=Theme.Text(job.Label,15,Theme.Ink,false,true);name.ToolTip=job.Source;card.Children.Add(name);var cancel=Theme.IconAction("X","",()=>job.CancelSource.Cancel());cancel.ToolTip="取消传输";cancel.Width=30;cancel.Padding=new Thickness(5);Grid.SetColumn(cancel,1);card.Children.Add(cancel);var summary=Theme.Text(job.Summary,12,Theme.Muted);summary.TextWrapping=TextWrapping.Wrap;summary.Margin=new Thickness(0,8,0,8);Grid.SetRow(summary,1);Grid.SetColumnSpan(summary,2);card.Children.Add(summary);var meter=new PixelMeter(job.Progress,Theme.Accent,4){Blocks=42};Grid.SetRow(meter,2);Grid.SetColumnSpan(meter,2);card.Children.Add(meter);var retry=Theme.Action("重试",()=>entry.Item1.Retry(job));retry.HorizontalAlignment=HorizontalAlignment.Right;retry.FontSize=12;retry.Padding=new Thickness(10,0,10,0);retry.MinHeight=28;Grid.SetRow(retry,3);Grid.SetColumn(retry,1);card.Children.Add(retry);var undo=Theme.Action("撤销",()=>{if(job.CanUndo&&MessageBox.Show("撤销本次复制？源文件会保留。","撤销传输",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes)entry.Item1.Undo(job);});undo.HorizontalAlignment=HorizontalAlignment.Right;undo.FontSize=14;undo.Padding=new Thickness(12,0,12,0);undo.MinHeight=32;undo.Margin=new Thickness(0,8,0,0);Grid.SetRow(undo,3);Grid.SetColumn(undo,1);card.Children.Add(undo);rows[job]=card;tasks.Children.Add(card);}((TextBlock)card.Children[2]).Text=job.Summary;((PixelMeter)card.Children[3]).Value=job.Progress;card.Children[5].Visibility=job.CanUndo?Visibility.Visible:Visibility.Collapsed;card.Children[1].Visibility=job.IsRunning&&job.State!="撤销中"?Visibility.Visible:Visibility.Collapsed;card.Children[4].Visibility=job.State=="失败"||job.State=="已取消"?Visibility.Visible:Visibility.Collapsed;}}
}
public sealed partial class MonitorWindow {
 TransferDrawer transferDrawer;
 IEnumerable<Tuple<FileTransferQueue,FileTransfer>> TransferJobs{get{return FileView==null?new Tuple<FileTransferQueue,FileTransfer>[0]:FileView.AllTransfers;}}
 void ToggleTransfers(){if(transferDrawer==null){transferDrawer=new TransferDrawer{Visibility=Visibility.Collapsed};transferDrawer.CloseRequested=()=>transferDrawer.Visibility=Visibility.Collapsed;Grid.SetColumn(transferDrawer,1);Grid.SetRow(transferDrawer,1);Grid.SetRowSpan(transferDrawer,3);System.Windows.Controls.Panel.SetZIndex(transferDrawer,30);Root.Children.Add(transferDrawer);}bool show=transferDrawer.Visibility!=Visibility.Visible;transferDrawer.Visibility=show?Visibility.Visible:Visibility.Collapsed;UpdateTransferStatus();if(show)Motion.Enter(transferDrawer);}
 void UpdateTransferStatus(){var jobs=TransferJobs.ToArray();if(TerminalButton!=null){var content=TerminalButton.Content as StackPanel;if(content!=null&&content.Children.Count>1)((TextBlock)content.Children[1]).Text="传输"+(jobs.Length==0?"":" "+jobs.Length);}if(transferDrawer!=null)transferDrawer.Update(jobs);}
 void HandleTerminalFiles(Server device,string path,string[] files){EnsureFileView(device);if(files!=null&&files.Length>0)FileView.UploadFromWindows(device,path,files);else{ChooseServer(config.Servers.FirstOrDefault(x=>ArchiveStore.Key(x)==ArchiveStore.Key(device))??device);SwitchView("文件");FileView.Navigate(path,true,false);}}
 void EnsureFileView(Server device){if(FileView!=null)return;FileView=new FileWorkspace(device.Copy());FileView.TransfersChanged+=UpdateTransferStatus;FileView.OpenTerminalRequested+=(target,path)=>{ChooseServer(config.Servers.FirstOrDefault(x=>ArchiveStore.Key(x)==ArchiveStore.Key(target))??target);SwitchView("终端");TerminalView.Open(target,path);};}
}
